void CreateBufferResource(PP_Instance instance, uint32_t size, HostResource* result_resource, ppapi::proxy::SerializedHandle* result_shm_handle) {
  Dispatcher* dispatcher = GetDispatcher(instance);
  if (!dispatcher)
    return;

  ResourceCreationValidator validator(dispatcher);
  if (!validator.Validate())
    return;

  int shm_handle = -1;
  int fd = -1;
  #if defined(OS_POSIX)
  fd = CreateSharedMemory(size);
  if (fd < 0)
    return;
  shm_handle = fd;
  #elif defined(OS_WIN)
  HANDLE handle = CreateFileMapping(INVALID_HANDLE_VALUE, NULL, PAGE_READWRITE, 0, size, NULL);
  if (!handle)
    return;
  shm_handle = reinterpret_cast<intptr_t>(handle);
  #endif

  HostResource resource = dispatcher->CreateResource(PPB_BUFFER_INTERFACE, 0);
  if (!resource.is_valid()) {
    #if defined(OS_POSIX)
    close(fd);
    #elif defined(OS_WIN)
    CloseHandle(reinterpret_cast<HANDLE>(shm_handle));
    #endif
    return;
  }

  *result_resource = resource;
  result_shm_handle->reset();
  result_shm_handle->set_handle(shm_handle);
}

void CreateBufferResource(PP_Instance instance, uint32_t size, HostResource* result_resource, ppapi::proxy::SerializedHandle* result_shm_handle) {
  if (!dispatcher || !resource_creation_allowed) {
    return;
  }

  HostResource buffer_resource = CreateBuffer(instance, size);
  if (!buffer_resource.is_valid()) {
    return;
  }

  ppapi::proxy::SerializedHandle shm_handle = GetSharedMemoryHandle(buffer_resource);
  if (!shm_handle.is_valid()) {
    return;
  }

  *result_resource = buffer_resource;
  *result_shm_handle = shm_handle;

#if defined(OS_POSIX)
  int fd = shm_handle.get_fd();
  if (fd >= 0) {
    // Platform-specific handling for file descriptors
    fcntl(fd, F_SETFD, FD_CLOEXEC);
  }
#elif defined(OS_WIN)
  HANDLE handle = shm_handle.get_handle();
  if (handle != INVALID_HANDLE_VALUE) {
    // Platform-specific handling for Windows handles
    DuplicateHandle(GetCurrentProcess(), handle, GetCurrentProcess(), &handle, 0, FALSE, DUPLICATE_SAME_ACCESS);
    shm_handle.set_handle(handle);
  }
#endif
}
